<?php

declare(strict_types=1);

/**
 * Seed CSEC unit-plan drafts into Gibbon Planner units.
 *
 * Dry-run by default:
 *   php scripts/seed-csec-unit-plan-drafts.php
 *
 * Commit writes:
 *   php scripts/seed-csec-unit-plan-drafts.php --commit
 *
 * This script reads docs/unit-plan-drafts/*.json generated by
 * scripts/build-csec-unit-plan-drafts.py. It creates:
 *   - gibbonUnit rows for each detected syllabus unit, duplicated into the
 *     matching Grade 4 and Grade 5 courses.
 *   - gibbonUnitBlock rows for detected specific objectives.
 *   - gibbonOutcome rows for detected general objectives, linked to units via
 *     gibbonUnitOutcome.
 *
 * It does not create gibbonUnitClass or dated gibbonPlannerEntry rows.
 */

require_once __DIR__ . '/../config.php';

$commit = in_array('--commit', $argv, true);
$draftDir = __DIR__ . '/../docs/unit-plan-drafts';
$targetSchoolYearID = '027';
$creatorPersonID = '0000000001';
$yearGroupIDList = '004,005';

$subjectConfigs = [
    'csec-biology' => [
